
let tarefas = JSON.parse(localStorage.getItem("tarefas")) || [];

let proximoCodigo = Number(
    localStorage.getItem("proximoCodigo")
    ) || 1;


    // 1. SALVAR OS DADOS
    function salvarDados() {
        localStorage.setItem("tarefas", JSON.stringify(tarefas));

            localStorage.setItem(
                    "proximoCodigo",
                            proximoCodigo
                                );
                                }


                                // 2. VALIDAR OS DADOS
                                function validarTarefa(titulo, descricao) {
                                    if (titulo.trim() === "") {
                                            alert("Digite o título da tarefa.");
                                                    return false;
                                                        }

                                                            if (descricao.trim() === "") {
                                                                    alert("Digite a descrição da tarefa.");
                                                                            return false;
                                                                                }

                                                                                    return true;
                                                                                    }


                                                                                    // 3. CADASTRAR UMA TAREFA
                                                                                    function cadastrarTarefa(titulo, descricao, prioridade) {

                                                                                        if (!validarTarefa(titulo, descricao)) {
                                                                                                return;
                                                                                                    }

                                                                                                        let tarefa = {
                                                                                                                codigo: proximoCodigo,
                                                                                                                        titulo: titulo,
                                                                                                                                descricao: descricao,
                                                                                                                                        prioridade: prioridade,
                                                                                                                                                concluida: false
                                                                                                                                                    };

                                                                                                                                                        tarefas.push(tarefa);

                                                                                                                                                            proximoCodigo++;

                                                                                                                                                                salvarDados();

                                                                                                                                                                    listarTarefas();

                                                                                                                                                                        alert("Tarefa cadastrada com sucesso!");
                                                                                                                                                                        }


                                                                                                                                                                        // 4. CAPTURAR OS DADOS DO FORMULÁRIO
                                                                                                                                                                        document.getElementById("formTarefa")
                                                                                                                                                                            .addEventListener("submit", function(event) {

                                                                                                                                                                                    event.preventDefault();

                                                                                                                                                                                            let titulo = document.getElementById("titulo").value;
                                                                                                                                                                                                    let descricao = document.getElementById("descricao").value;
                                                                                                                                                                                                            let prioridade = document.getElementById("prioridade").value;

                                                                                                                                                                                                                    cadastrarTarefa(titulo, descricao, prioridade);

                                                                                                                                                                                                                            document.getElementById("formTarefa").reset();
                                                                                                                                                                                                                                });


                                                                                                                                                                                                                                // 5. LISTAR AS TAREFAS
                                                                                                                                                                                                                                function listarTarefas(lista = tarefas) {

                                                                                                                                                                                                                                    let area = document.getElementById("listaTarefas");

                                                                                                                                                                                                                                        area.innerHTML = "";

                                                                                                                                                                                                                                            if (lista.length === 0) {
                                                                                                                                                                                                                                                    area.innerHTML = "<p>Nenhuma tarefa encontrada.</p>";
                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                    lista.forEach(function(tarefa) {

                                                                                                                                                                                                                                                                            let status = tarefa.concluida
                                                                                                                                                                                                                                                                                        ? "Concluída"
                                                                                                                                                                                                                                                                                                    : "Pendente";

                                                                                                                                                                                                                                                                                                            let classe = tarefa.concluida
                                                                                                                                                                                                                                                                                                                        ? "concluida"
                                                                                                                                                                                                                                                                                                                                    : "pendente";

                                                                                                                                                                                                                                                                                                                                            let div = document.createElement("div");

                                                                                                                                                                                                                                                                                                                                                    div.className = "tarefa";

                                                                                                                                                                                                                                                                                                                                                            div.innerHTML = `
                                                                                                                                                                                                                                                                                                                                                                        <h3>${tarefa.titulo}</h3>

                                                                                                                                                                                                                                                                                                                                                                                    <p><strong>Código:</strong> ${tarefa.codigo}</p>

                                                                                                                                                                                                                                                                                                                                                                                                <p><strong>Descrição:</strong> ${tarefa.descricao}</p>

                                                                                                                                                                                                                                                                                                                                                                                                            <p><strong>Prioridade:</strong> ${tarefa.prioridade}</p>

                                                                                                                                                                                                                                                                                                                                                                                                                        <p class="${classe}">
                                                                                                                                                                                                                                                                                                                                                                                                                                        <strong>Status:</strong> ${status}
                                                                                                                                                                                                                                                                                                                                                                                                                                                    </p>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                <button onclick="concluirTarefa(${tarefa.codigo})">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Concluir
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </button>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <button onclick="alterarPrioridade(${tarefa.codigo})">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Alterar prioridade
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            `;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    area.appendChild(div);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // 6. BUSCAR UMA TAREFA COM FIND
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function buscarTarefa() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            let codigo = Number(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("codigoBusca").value
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            let tarefa = tarefas.find(function(item) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return item.codigo === codigo;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (tarefa) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    listarTarefas([tarefa]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                alert("Tarefa não encontrada.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // 7. CONCLUIR UMA TAREFA
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function concluirTarefa(codigo) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        let tarefa = tarefas.find(function(item) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return item.codigo === codigo;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (tarefa) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                tarefa.concluida = true;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        salvarDados();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                listarTarefas();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        alert("Tarefa concluída!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // 8. ALTERAR A PRIORIDADE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function alterarPrioridade(codigo) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let tarefa = tarefas.find(function(item) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return item.codigo === codigo;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (tarefa) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (tarefa.prioridade === "Baixa") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    tarefa.prioridade = "Média";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } else if (tarefa.prioridade === "Média") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        tarefa.prioridade = "Alta";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            tarefa.prioridade = "Baixa";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            salvarDados();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    listarTarefas();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            alert("Prioridade alterada!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // 9. EXIBIR AS TAREFAS AO ABRIR A PÁGINA
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                listarTarefas();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                